                    try {
                        const childDoc =
                            frame.contentDocument;

                        if (!childDoc) return;

                        cleanDocument(
                            childDoc
                        );

                        observeDocument(
                            childDoc
                        );

                    } catch (_) {}
                }

                frame.addEventListener(
                    'load',
                    inspect
                );

                inspect();
            });

        } catch (_) {}
    }


    const observedDocs =
        new WeakSet();

    function observeDocument(doc) {
        if (
            !doc ||
            observedDocs.has(doc)
        ) {
            return;
        }

        observedDocs.add(doc);

        const observer =
            new MutationObserver(
                mutations => {

                    for (
                        const mutation
                        of mutations
                    ) {
                        for (
                            const node
                            of mutation.addedNodes
                        ) {
                            if (
                                node.nodeType !==
                                Node.ELEMENT_NODE
                            ) {
                                continue;
                            }

                            if (
                                shouldKillNode(node)
                            ) {
                                remove(
                                    node,
                                    'dynamic ad'
                                );
                            }
                        }
                    }

                    cleanDocument(doc);
                    hookFrames(doc);
                }
            );

        observer.observe(
            doc.documentElement ||
            doc,
            {
                childList: true,
                subtree: true
            }
        );
    }


    function start() {
        if (!document.documentElement) {
            requestAnimationFrame(start);
            return;
        }

        /*
         * CSS catches ad containers before JS removal,
         * reducing visible flashes.
         */
        const style =
            document.createElement('style');

        style.textContent = `
            .adsbygoogle,
            .advertisement,
            .advertising,
            .ad-container,
            .ads-container,
            .ad-wrapper,
            .ads-wrapper,
            .banner-ad,
            .banner-ads,
            .popup-ad,
            .popunder,
            .interstitial,
            [data-ad],
            [data-ad-slot],
            [data-ad-client] {
                display: none !important;
                visibility: hidden !important;
                pointer-events: none !important;
            }
        `;

        (
            document.head ||
            document.documentElement
        ).appendChild(style);

        cleanDocument(document);
        hookFrames(document);
        observeDocument(document);

        /*
         * Rotating ad networks occasionally inject between
         * MutationObserver passes.
         */
        setInterval(() => {
            cleanDocument(document);
            hookFrames(document);
        }, 700);

        console.log(
            TAG,
            'Protection active'
        );
    }

    start();

})();

