      });

      if (!response.ok) {
        throw new Error('HTTP ' + response.status);
      }

      return await response.json();
    } finally {
      clearTimeout(timer);
    }
  }

  function say(message) {
    if (statusNode && statusNode.textContent !== message) {
      statusNode.textContent = message;
    }
  }

  function renderStatus() {
    if (!frame) {
      return say(
        'Auto intro: select an episode and start the player.'
      );
    }

    if (failedSeek) {
      return say(
        'Auto intro: player did not confirm seeking. Try Vidplay, then Retry.'
      );
    }

    if (pending) {
      return say(
        'Auto intro: skipping; waiting for the player to confirm…'
      );
    }

    if (done) {
      return say(
        note || 'Auto intro: opening already passed.'
      );
    }

    if (!protocol) {
      return say(
        'Auto intro: waiting for player messages. Vidplay / EchoVideo is supported; PlayMogo is unverified.'
      );
    }

    if (range) {
      return say(
        'Auto intro: armed ' +
        stamp(range.start) +
        '–' +
        stamp(range.end) +
        ' (' +
        rangeSource +
        ').'
      );
    }

    return say(
      loading
        ? 'Auto intro: looking up opening timestamps…'
        : note || 'Auto intro: waiting for video duration.'
    );
  }

  function add(tag, text, parent) {
    const element = document.createElement(tag);

    if (text) element.textContent = text;
    if (parent) parent.appendChild(element);

    return element;
  }

  function makeUI() {
    if (ui && ui.isConnected) return;

    const host =
      document.querySelector('#w-player') ||
      document.querySelector('#player-wrapper');

    if (!host) return;

    ui = add('div', '', host);
    ui.id = 'notme-ani-intro';

    ui.style.cssText =
      'padding:10px 12px;' +
      'margin:8px 0;' +
      'background:#181818;' +
      'color:#eee;' +
      'border:1px solid #454545;' +
      'border-radius:8px;' +
      'font:13px/1.5 sans-serif;';

    statusNode = add('div', '', ui);

    const details = add('details', '', ui);
    add('summary', 'Intro settings / Retry', details);

    add(
      'p',
      'Automatic skipping needs opening timestamps. If anime matching fails, choose the correct anime or enter its MyAnimeList ID once. No fixed 90-second guess.',
      details
    );

    choices = add('select', '', details);
    choices.style.cssText =
      'max-width:100%;display:none;margin:5px 0;';

    choices.addEventListener('change', () => {
      if (choices.value) {
        saveMal(Number(choices.value));
      }
    });

    const form = add('form', '', details);
    const label = add('label', 'MyAnimeList ID: ', form);

    malInput = add('input', '', label);
    malInput.type = 'number';
    malInput.min = '1';
    malInput.placeholder = 'Anime ID';
    malInput.style.width = '100px';

    const save = add('button', 'Save / Retry', form);
    save.type = 'submit';

    form.addEventListener('submit', event => {
      event.preventDefault();

      const id = Number(malInput.value);

      if (Number.isInteger(id) && id > 0) {
        saveMal(id);
      } else {
        retry();
      }
    });

    const manual = add('form', '', details);

    add(
      'p',
      'Optional: opening start/end for this episode, in seconds or m:ss. This is used only if you save it.',
      manual
    );

    startInput = add('input', '', manual);
    startInput.placeholder = 'Start, e.g. 1:20';
    startInput.style.width = '120px';

    endInput = add('input', '', manual);
    endInput.placeholder = 'End, e.g. 2:50';
    endInput.style.width = '120px';

    const apply = add(
      'button',
      'Save episode times',
      manual
    );

    apply.type = 'submit';

    manual.addEventListener('submit', event => {
      event.preventDefault();

      const selectedRange = validRange(
        seconds(startInput.value),
        seconds(endInput.value)
      );

      if (!selectedRange) {
        note =
          'Auto intro: enter valid opening start/end times.';
        say(note);
        return;
      }

      write(
        'notme.aniintro.manual.' + show + '.' + episode,
        selectedRange
      );

      range = selectedRange;
      rangeSource = 'your episode times';
      pending = null;
      attempts = 0;
      done = false;
      failedSeek = false;

      seekIfNeeded();
      renderStatus();
    });
  }

  function populateChoices() {
    if (!choices) return;

    choices.replaceChildren();

    const first = add(
      'option',
      'Choose the correct anime…',
      choices
    );

    first.value = '';

    for (const candidate of candidates) {
      const option = add(
        'option',
        candidate.title +
          (candidate.year ? ' (' + candidate.year + ')' : ''),
        choices
      );

      option.value = String(candidate.mal_id);
    }

    choices.style.display =
      candidates.length ? 'block' : 'none';
  }

  function retry() {
    generation++;

    loading = false;
    fetchedKey = '';
    triedLookup = false;
    pending = null;
    failedSeek = false;
    attempts = 0;
    note = '';
    done = false;

    if (frame && protocol === 'echo') {
      send({
        channel: 'megacloud',
        event: 'request_state'
      });
    }

    loadRange();
    renderStatus();
  }

  function saveMal(id) {
    write(malKey(), id);

    candidates = [];
    populateChoices();

    range = null;
    rangeSource = '';

    retry();
  }

  function sync() {
    makeUI();

    const watch = document.querySelector('#watch-main');

    const nextFrame =
      document.querySelector('#player iframe') ||
      document.querySelector('#player-wrapper iframe');

    const active = document.querySelector(
      '#w-episodes a.active[data-num]'
    );

    const nextEpisode =
      Number(active && active.getAttribute('data-num')) ||
      Number(
        (location.pathname.match(/\/ep-([\d.]+)/) || [])[1]
      ) ||
      Number(watch && watch.getAttribute('data-ep-name'));

    const showId =
      (watch && watch.getAttribute('data-id')) ||
      (location.pathname.match(/\/watch\/([^/]+)/) || [])[1] ||
      '';

    const src =
      (nextFrame && nextFrame.getAttribute('src')) || '';

    const nextContext =
      showId + ':' + nextEpisode + ':' + src;

    if (
      nextContext !== context ||
      nextFrame !== frame
    ) {
      context = nextContext;
      generation++;

      frame = nextFrame;
      show = showId;
      episode = nextEpisode;
      manager = null;
      frameOrigin = '';

      try {
        frameOrigin = new URL(src, location.href).origin;
      } catch (_) {}

      range = null;
      rangeSource = '';
      time = null;
      duration = 0;
      paused = null;
      done = false;
      protocol = '';

      pending = null;
      attempts = 0;
      failedSeek = false;
      loading = false;
      fetchedKey = '';
      triedLookup = false;
      note = '';
      candidates = [];

      const heading =
        document.querySelector('#watch-main h1.title') ||
        document.querySelector('h1');

      titles = heading
        ? [
            heading.getAttribute('data-jp'),
            heading.textContent
          ].filter(Boolean)
        : [];

      if (malInput) {
        malInput.value = read(malKey()) || '';
      }

      if (startInput) startInput.value = '';
      if (endInput) endInput.value = '';

      populateChoices();

      log(
        'Episode ' + episode + ' player ' + frameOrigin
      );

      if (
        /^https:\/\/play\.echovideo\.ru$/i.test(frameOrigin)
      ) {
        protocol = 'echo';

        send({
          channel: 'megacloud',
          event: 'request_state'
        });
      }
    }

    try {
      manager =
        window.jQuery &&
        window.jQuery('#watch-main').data('WatchManager');
    } catch (_) {}

    if (frame && protocol === 'echo') {
      send({
        channel: 'megacloud',
        event: 'request_state'
      });
    }

    loadRange();
    seekIfNeeded();
    renderStatus();
  }

  async function loadRange() {
    if (
      !show ||
      !Number.isInteger(episode) ||
      episode < 1 ||
      range
    ) {
      return;
    }

    const saved = read(
      'notme.aniintro.manual.' + show + '.' + episode
    );

    if (saved) {
      range = validRange(saved.start, saved.end);

      if (range) {
        rangeSource = 'your episode times';
        return;
      }
    }

    const native =
      manager &&
      manager.Xr &&
      manager.Xr.intro;

    if (Array.isArray(native)) {
      range = validRange(native[0], native[1]);

      if (range) {
        rangeSource = 'AniWaves';
        return;
      }
    }

    if (
      !duration ||
      loading ||
      !frame ||
      !protocol
    ) {
      return;
    }

    const token = generation;
    loading = true;

    try {
      let id = Number(read(malKey()));

      if (!Number.isInteger(id) || id < 1) {
        id =
          titles
            .map(title => knownMals[normalize(title)])
            .find(Boolean) || 0;

        if (id) {
          write(malKey(), id);
          if (malInput) malInput.value = id;
        }
      }

      if (!Number.isInteger(id) || id < 1) {
        if (triedLookup) return;

        triedLookup = true;

        const query = titles[0];

        if (!query) {
          note =
            'Auto intro: enter the MyAnimeList ID in Intro settings.';
          return;
        }

        const result = await json(
          'https://api.jikan.moe/v4/anime?limit=10&q=' +
          encodeURIComponent(query)
        );

        if (token !== generation) return;

        candidates = (result.data || []).filter(
          candidate => Number.isInteger(candidate.mal_id)
        );

        const exact = candidates.filter(candidate => {
          const names = [
            candidate.title,
            candidate.title_english,
            ...(candidate.title_synonyms || []),
            ...(candidate.titles || []).map(item => item.title)
          ];

          return names.some(name =>
            titles.some(ours =>
              normalize(name) &&
              normalize(name) === normalize(ours)
            )
          );
        });

        if (exact.length !== 1) {
          populateChoices();

          note =
            'Auto intro: choose the correct anime in Intro settings.';
          return;
        }

        id = exact[0].mal_id;
        write(malKey(), id);

        if (malInput) malInput.value = id;

        candidates = [];
        populateChoices();
      }

      const key =
        id + ':' + episode + ':' + Math.round(duration);

      if (fetchedKey === key) return;

      fetchedKey = key;

      const result =
        cache.get(key) ||
        await json(
          'https://api.aniskip.com/v2/skip-times/' +
          id +
          '/' +
          episode +
          '?types%5B%5D=op&episodeLength=' +
          duration.toFixed(3)
        );

      if (token !== generation) return;

      cache.set(key, result);

      const openings = (result.results || [])
        .filter(item =>
          item.skipType === 'op' &&
          item.interval &&
          Number.isFinite(Number(item.episodeLength)) &&
          Math.abs(Number(item.episodeLength) - duration) <= 6
        )
        .sort(
          (a, b) =>
            Math.abs(Number(a.episodeLength) - duration) -
            Math.abs(Number(b.episodeLength) - duration)
        );

      for (const opening of openings) {
        const selectedRange = validRange(
          opening.interval.startTime,
          opening.interval.endTime
        );

        if (selectedRange) {
          range = selectedRange;
          rangeSource = 'AniSkip';
          note = '';

          log(
            'Opening ' +
            selectedRange.start +
            '–' +
            selectedRange.end
          );

          break;
        }
      }

      if (!range) {
        note =
          'Auto intro: no matching opening times for this episode/version. Optional episode times are in settings.';
      }
    } catch (error) {
      if (token === generation) {
        note =
          'Auto intro: timestamp lookup failed. Use Save / Retry in Intro settings.';

        log(note);
      }
    } finally {
      if (token === generation) {
        loading = false;
        seekIfNeeded();
        renderStatus();
      }
    }
  }

  function send(message) {
    if (
      !frame ||
      !frame.contentWindow ||
      !/^https?:\/\//.test(frameOrigin)
    ) {
      return false;
    }

    try {
      frame.contentWindow.postMessage(
        JSON.stringify(message),
        frameOrigin
      );

      return true;
    } catch (_) {
      return false;
    }
  }

  function seekIfNeeded() {
    if (
      !range ||
      time === null ||
      !duration ||
      done ||
      failedSeek ||
      paused === true
    ) {
      return;
    }

    if (!validRange(range.start, range.end)) return;

    if (pending) {
      if (
        time >= pending.to - 0.8 &&
        time - pending.from > 2
      ) {
        pending = null;
        done = true;
        note = 'Auto intro: intro skipped.';

        log('Seek confirmed.');
        return;
      }

      if (Date.now() < pending.deadline) return;

      pending = null;

      if (attempts >= 2) {
        failedSeek = true;
        log('Seek was not confirmed.');
        return;
      }
    }

    if (time >= range.end) {
      done = true;
      note = 'Auto intro: opening already passed.';
      return;
    }

    if (time < range.start) return;

    const message =
      protocol === 'echo'
        ? {
            channel: 'megacloud',
            event: 'seek',
            time: range.end
          }
        : protocol === 'legacy'
          ? {
              cmd: 'SEEK',
              value: range.end
            }
          : null;

    if (!message) return;

    if (send(message)) {
      attempts++;

      pending = {
        from: time,
        to: range.end,
        deadline: Date.now() + 6000
      };

      log(
        'Seek requested via ' +
        protocol +
        ', attempt ' +
        attempts
      );
    }
  }

  function onMessage(event) {
    if (
      !frame ||
      event.source !== frame.contentWindow ||
      event.origin !== frameOrigin
    ) {
      return;
    }

    let message = event.data;

    try {
      if (typeof message === 'string') {
        message = JSON.parse(message);
      }
    } catch (_) {
      return;
    }

    if (!message || typeof message !== 'object') return;

    let currentTime;
    let currentDuration;

    if (
      message.channel === 'megacloud' &&
      ['time', 'state', 'play', 'pause', 'ready'].includes(
        message.event
      )
    ) {
      protocol = 'echo';
      currentTime = Number(message.time);
      currentDuration = Number(message.duration);

      if (message.event === 'play') paused = false;
      if (message.event === 'pause') paused = true;

      if (typeof message.paused === 'boolean') {
        paused = message.paused;
      }
    } else if (
      message.event === 'PLAY_TIMING' &&
      message.data &&
      Number.isFinite(Number(message.data.position))
    ) {
      protocol = 'legacy';
      currentTime = Number(message.data.position);
      currentDuration = Number(message.data.duration);

      if (typeof message.data.paused === 'boolean') {
        paused = message.data.paused;
      }
    } else {
      return;
    }

    if (
      Number.isFinite(currentTime) &&
      currentTime >= 0
    ) {
      time = currentTime;
    }

    if (
      Number.isFinite(currentDuration) &&
      currentDuration > 0
    ) {
      duration = currentDuration;
    }

    loadRange();
    seekIfNeeded();
    renderStatus();
  }

  window.addEventListener('message', onMessage);

  window.addEventListener(
    'pagehide',
    () => {
      clearInterval(pulseTimer);
      window.removeEventListener('message', onMessage);
    },
    { once: true }
  );

  // App injection may happen after DOMContentLoaded.
  sync();
  pulseTimer = setInterval(sync, 1000);
})();
